-- source: next steps written for the existing description, which already sets out the five-station circuit and the freeze-for-a-count habit
UPDATE public.drill_resources SET
  regression_notes = 'Run two stations instead of five, with tossed balls rather than pitched ones. Beating the ball to the spot is learnable slowly and not at all in a hurry.',
  progression_notes = 'Increase velocity, work only the edges of the zone, and film from behind the plate so the catcher sees what an umpire sees.',
