  updated_at = now()
WHERE id = '5f398d5c-6377-4119-b5b7-99b81f4b8028';

-- Catcher Throw-Down Footwork to Second  [Catching]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out the dry-then-toss-then-live progression and the timed reps
UPDATE public.drill_resources SET
  description = 'Catcher footwork for the throw to second, built in three stages. Dry first: no ball, just the replace step and the jab step, until the feet move without thought. Then from a partner''s toss. Then live off a machine or a pitcher. Three sets of six throw-downs, every one timed glove to glove. The exchange happens during the footwork rather than after it, and that overlap is where pop time is actually found — not in a stronger arm.',
  regression_notes = 'Dry footwork only, with no ball and no clock. A catcher thinking about the throw stops moving their feet properly, which is the thing being built.',
  progression_notes = 'Add live pitching at game speed, then a runner actually stealing, so the throw has a real target and a real deadline.',
  reps_guidance = '3 sets of 6 throw-downs, timed',
  practice_roles = ARRAY['isolate', 'progress']::text[],
  updated_at = now()
WHERE id = '367642e8-dfd4-4988-90e5-f2c4d10b3401';

-- Game-Speed Reaction Blocking  [Catching]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out the random locations and the two-one-zero scoring
UPDATE public.drill_resources SET
  description = 'Blocking at game speed with nothing telegraphed. Balls are thrown or machine-fed into the dirt at random locations and the catcher has to read and react rather than pre-set to a side. Three rounds of ten, scored: two points for a ball blocked and kept in front, one for a ball blocked but pushed away, nothing for one that gets past. A runner-on-third scenario is added so recovering to a throwing position matters as much as the block itself.',
  regression_notes = 'Go back to announced locations at reduced speed, or to the technique drill with placed and rolled balls. Reaction work on top of unsound mechanics builds a flinch.',
  progression_notes = 'Increase velocity, add a runner who actually advances on anything not kept in front, and score the recovery throw as well as the block.',
  reps_guidance = '3 rounds of 10 random blocks, scored',
  practice_roles = ARRAY['progress', 'game_application']::text[],
  updated_at = now()
WHERE id = '808e703f-d60e-4a0b-8cbd-845bcb4cc1bb';

-- Youth Receiving Foundations — Quiet Glove & Soft Hands  [Catching]  → READY
-- source: next steps written for the existing description, which already sets out the quiet-glove standard and the soft-hands receiving
UPDATE public.drill_resources SET
  regression_notes = 'Toss underhand from short range with a soft ball, and work one zone at a time. A young catcher fighting the ball needs slower pitches, not more cues.',
  progression_notes = 'Move to the five-station framing circuit, then to live pitching. The quiet glove is the foundation everything else in the category is built on.',
  updated_at = now()
WHERE id = 'e7bd95b6-d491-49e2-a383-7fc381e7b0ce';

-- Blocking the Right Way — Technique to Reaction Reps  [Catching]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out the placed-to-rolled-to-thrown progression and the block shape
UPDATE public.drill_resources SET
  description = 'Blocking built from the shape outwards. Stage one: balls placed on the ground, no throw, so the catcher can drop into position and feel it — knees replacing the feet, chin tucked, shoulders rounded so the chest angles the ball back toward the plate. Stage two: rolled balls. Stage three: short-hop throws to the middle, the glove side and the arm side. Three sets of eight. On lateral blocks the push comes off the opposite foot, which is the part that has to be drilled rather than explained.',
  regression_notes = 'Placed balls only, in full gear, with no throw at all. The shape has to be comfortable before a ball is moving toward it.',
  progression_notes = 'Move to the game-speed reaction version with random locations, and add a recovery throw so the block finishes as a completed play.',
  reps_guidance = '3 sets of 8 blocks (middle, glove-side, arm-side)',
  updated_at = now()
WHERE id = 'babe5481-655c-4c2e-9985-2465937c1067';

-- Hip Lead Drill  [Pitching]  → READY
-- source: written from the existing description and cue (lead with the hip toward home, the arm follows) and the recorded flaws it fixes
UPDATE public.drill_resources SET
  description = 'The order of the pitching delivery, isolated at the one point where it goes wrong. From the balance point at the top of the leg lift, the pitcher moves toward the plate hip first — the front hip leads down the mound while the shoulders and throwing arm stay back. They hold that separated position, then finish the pitch. Ten repetitions slowly, then at normal speed. A pitcher whose shoulders go with the hip has nothing left to generate velocity with.',
  ai_coaching_notes = 'Have them stop and hold the moment the hip has moved but the shoulders have not, so they can feel the stretch across the middle. ''Your hip goes first, your arm follows.'' Watch from the side: the front hip should be visibly ahead of the front shoulder on the way down. Leaking — the whole body drifting early — looks similar and is the opposite, so check that the back leg is still loaded.',
  regression_notes = 'Do it without a ball, from a standing start rather than a full leg lift, and just walk the hip forward. The feel is the whole lesson.',
  progression_notes = 'Remove the hold so the sequence flows, then throw at full speed to a catcher and check whether the separation survives. Pair it with the Balance Point drill if the leg lift is unstable.',
  success_markers = ARRAY['Front hip moves toward the plate before the shoulders do', 'Can hold the separated position for a count without falling forward', 'Back leg stays loaded rather than the whole body drifting']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = 'e5d28c39-30b0-48fd-9534-8a43cd8154db';

-- Wrist Snap Drill  [Pitching]  → READY
-- source: written from the existing description and cue (isolate the wrist snap, pull the fingers down the back of the ball)
UPDATE public.drill_resources SET
  description = 'The wrist snap on its own, with everything else removed. The pitcher kneels or stands close to a partner or a wall, holds the throwing arm up with the elbow supported by the glove hand, and flips the ball using only the wrist. The fingers pull down the back of the ball at release, producing visible backspin. Twenty to thirty flips. The ball should travel only a few feet and rotate cleanly — distance is not the goal and chasing it reintroduces the arm.',
  ai_coaching_notes = 'Hold their elbow for the first few if the arm keeps joining in; the isolation is what makes this work. Look at the spin, not the flight — tight backspin means the fingers stayed behind the ball, and a wobbling ball means they came off the side of it. Close range only. A player throwing this thirty feet has turned it back into a throw.',
  regression_notes = 'Have a coach hold the elbow and use a tennis ball. Feeling the wrist work in isolation is the entire objective and any setup that achieves it is fine.',
  progression_notes = 'Move to the kneeling throw where the wrist snap is combined with the arm and torso, then to the full delivery. The spin is what should carry through.',
  success_markers = ARRAY['Ball comes out with tight backspin rather than wobbling', 'Only the wrist moves — the elbow and shoulder stay still', 'Can repeat the spin on most flips rather than occasionally']::text[],
  equipment_needed = ARRAY['Baseball', 'Partner or wall']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = '77722605-74bc-44b8-9581-fdd1c7d9a4d3';

-- The Lawnmower Drill — Arm Action & Wrist Snap  [Pitching]  → READY
-- source: description rewritten to remove the brand-led attribution; markers and next steps written for the existing cues
UPDATE public.drill_resources SET
  description = 'Arm action drilled through a motion players already know: the pull that starts a lawnmower. The pitcher mimics that fast, loose downward pull with the throwing arm, snapping the wrist at the bottom of it. It isolates the arm action and the release without any of the lower half being involved, and the looseness is the point — a stiff arm is slower than a relaxed one, which is counterintuitive to most young pitchers until they feel the difference.',
  regression_notes = 'Do it slowly with no ball until the looseness is there. A player gripping the ball tightly will keep the arm tight no matter what they are told.',
  progression_notes = 'Add the ball, then throw to a target from a knee, then from the full delivery. Check whether the arm stays loose once the legs are involved.',
  success_markers = ARRAY['Arm moves loosely rather than rigidly through the pull', 'Wrist snaps at the bottom of the motion rather than staying locked', 'Player can describe the difference between a loose and a tight arm after a few reps']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = '25b42f9f-7769-47ac-ad0e-f9140091660e';

-- 4-Part Windup Drill — Breaking Down the Delivery  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out the four checkpoints and the stop-at-each-one method
UPDATE public.drill_resources SET
  regression_notes = 'Work two checkpoints instead of four, and hold each for a count of three. Four positions is a lot to hold in mind for a seven-year-old.',
  progression_notes = 'Join the checkpoints into one continuous slow delivery, then speed it up, then throw to a catcher. Go back to the checkpoint that breaks first.',
  success_markers = ARRAY['Stops balanced at each checkpoint instead of rushing through the motion', 'Can be stopped mid-delivery on command and hold the position', 'Full-speed delivery keeps the checkpoints rather than reverting']::text[],
  practice_roles = ARRAY['teach', 'isolate']::text[],
  updated_at = now()
WHERE id = '253fee8d-d86f-497b-83db-44e622fb0a2d';

-- Game-Speed Rundown Execution  [Team Defense]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out sprint-show-dart and the two-throw scoring
UPDATE public.drill_resources SET
  description = 'Rundowns at the speed they actually happen. Use the fastest players on the team as the runners, and score it: an out in two throws or fewer and the defence wins the repetition. Three things, in order — sprint to close the distance rather than jogging, show the ball high and early so the receiver can see it, and make a short dart throw only when the receiver calls for it. Fielders rotate behind the play at full speed. Eight to ten scored repetitions.',
  regression_notes = 'Drop to the calm rundown version at half speed with slower runners. Game speed on top of shaky rotation produces chaos rather than practice.',
  progression_notes = 'Add a second runner, or start the rundown from a live play rather than a set position so the defence has to organise itself under real conditions.',
  practice_roles = ARRAY['competition', 'game_application']::text[],
  updated_at = now()
WHERE id = '91bc52cf-a234-4ad3-97a6-6df6038c752c';

-- Calm Rundowns — Push Back, Follow Your Throw  [Team Defense]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out the push-back rule and the follow-your-throw rotation
UPDATE public.drill_resources SET
  description = 'Rundowns without the panic. Two lines of fielders at two bases with a runner trapped between them. Two rules and nothing else: always push the runner back toward the base they came from, so a failed rundown costs nothing; and always follow your throw to the back of the opposite line, so there is a fielder in place for the next one. Six to eight repetitions with the full rotation. Most youth rundowns fail because four players converge, nobody backs up, and the ball ends up in the outfield.',
  regression_notes = 'Go back to the two-base pickle with one throw and no rotation. The push-back rule is learnable before the rotation is.',
  progression_notes = 'Move to game speed with fast runners, then add a second runner so the defence has to decide which one to chase.',
  updated_at = now()
WHERE id = '2da70c16-18d3-4b63-8eca-12804ac048ea';

-- Two-Base Pickle Drill  [Team Defense]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out the ball-up rule and the one-throw target
UPDATE public.drill_resources SET
  description = 'The simplest rundown there is: two bases about forty feet apart, one fielder at each, one runner in between. The fielder with the ball runs hard at the runner holding the ball up by their ear where everyone can see it, and when the runner commits, the receiving fielder calls for it and takes the tag. Four to six repetitions per player in each role. Counting the throws out loud — and celebrating the one-throw outs — is what teaches them that running at the runner beats standing and faking.',
  regression_notes = 'Walk the runner rather than letting them sprint, so the fielders can practise running at them without it becoming a race they lose.',
  progression_notes = 'Add the push-back rule and the follow-your-throw rotation, which is the Calm Rundowns progression, then take it to game speed.',
  updated_at = now()
WHERE id = 'dac833d7-c4f6-42ce-8409-ea83dd77fa65';

-- Machine-Fed Relay Sequences at Game Speed  [Team Defense]  → READY
-- source: description rewritten to remove the brand-led attribution; next steps written for the existing cues
UPDATE public.drill_resources SET
  description = 'Full outfield-to-infield relays at game tempo, fed by a machine or a fungo on a fixed interval so the pace never drops. Balls go into the gaps and to the wall, and the defence runs complete sequences — outfielder to relay man to the base — including double cuts on the deepest balls. Three rounds of five sequences. Scoring it as runs prevented against bases gained turns it into a competition between defensive groups, which is what keeps the tempo honest.',
  regression_notes = 'Slow the feed interval and drop the double cuts. Single relays at a manageable pace are still the same skill and most youth teams have not mastered them.',
  progression_notes = 'Shorten the interval, add runners so the throw destination is a real decision, and time each sequence from the outfielder''s touch to the tag.',
  practice_roles = ARRAY['team_execution', 'competition']::text[],
  updated_at = now()
WHERE id = '62b2ed36-03da-4e9d-a424-1d94620fde7d';

-- Line Relay Race — Catch, Turn, Throw  [Team Defense]  → READY
-- source: next steps written for the existing description, which already sets out the two lines, the spacing and the race format
UPDATE public.drill_resources SET
  regression_notes = 'Shorten the links and use fewer players per line. A relay race where the throws cannot reach is a dropping contest, not a relay drill.',
  progression_notes = 'Lengthen the links, add a turn to the weak side, or require every player to call for the ball before it is thrown.',
  updated_at = now()
WHERE id = 'ef98c922-d86a-46ea-913c-903b41c8ba2e';

-- Cutoff Responsibilities by Situation  [Team Defense]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out the runners, the loud call and the role rotation
UPDATE public.drill_resources SET
  description = 'Cutoff assignments practised as decisions rather than as positions. Put runners on so every repetition has a real answer: runner on first, ball into left-centre — where does the throw go, and who is the cutoff? Six to eight situational repetitions, with the cutoff man calling ''cut two'', ''cut three'' or ''let it go'' loudly enough for the outfielder to hear. Players rotate through the cutoff role and the outfield role so both ends of the play get learned rather than one.',
  regression_notes = 'Run the Little League system walk-through first, with no runners and no ball. Assignments have to be known before they can be executed under pressure.',
  progression_notes = 'Add more complex situations — two runners, a ball to the wall — and let the cutoff man run the play without a coach calling it.',
  updated_at = now()
WHERE id = 'b1f220a4-fdc3-4750-810f-b431e0c8a16f';

-- Little League Cuts & Relays System  [Team Defense]  → READY
-- source: description expanded into setup and execution from the existing cues, which already set out the half-speed walk-through and the four scenarios
UPDATE public.drill_resources SET
  description = 'A cutoff system simple enough for a Little League team to actually run in a game. Walk the whole team through four scenarios at half speed with no ball — a ball to each outfield spot, with every player physically moving to where they belong. Then add a rolled ball, then a thrown one. Two live repetitions per scenario. The test is not whether it looks tidy but whether a player can answer ''ball in the right-centre gap, runner on first — where do you go?'' without looking around first.',
  regression_notes = 'Two scenarios instead of four, walked through with no ball at all. Every player knowing where to go on two situations beats everyone guessing on four.',
  progression_notes = 'Add live hit balls, then runners, then move to the situational version where the cutoff man makes the call rather than the coach.',
  updated_at = now()
WHERE id = '37f0c306-4c6c-4fa6-8491-96fa90893be9';

-- Flamingo Balance Drill — Single-Leg Stability  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out the single-leg hold and the escalating times
UPDATE public.drill_resources SET
  regression_notes = 'Hold for five seconds with a fingertip on a fence, then remove the support. Any duration held cleanly beats a longer one spent wobbling.',
  progression_notes = 'Close the eyes, stand on an uneven surface, or hold the balance point of an actual leg lift with the glove and ball in hand.',
  success_markers = ARRAY['Holds the position for thirty seconds without the other foot touching down', 'Ankle and hip stay quiet rather than constantly correcting', 'Can hold it on both legs, not just the strong one']::text[],
  practice_roles = ARRAY['isolate', 'warmup']::text[],
  updated_at = now()
WHERE id = 'a559ea0e-7d73-4920-905f-ccb86e117f4e';

-- Follow-Through Hold Drill — Finishing Strong  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out the three-second freeze and the four things to check
UPDATE public.drill_resources SET
  regression_notes = 'Throw at half effort and hold, or walk through the finish with no ball. A pitcher who cannot hold the finish is falling off, and that is easier to see slowly.',
  progression_notes = 'Hold the finish at full effort, then have a coach roll a ball at them immediately after release so the fielding-ready position has a purpose.',
  success_markers = ARRAY['Holds the finish for three seconds without stumbling', 'Chest finishes over the front knee with the throwing hand past the opposite hip', 'Ends in a position from which a ground ball could actually be fielded']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = '41ff62cc-fb54-4266-8d0c-083a1c341161';

-- The Heel-Toe Drill — Front Foot Landing  [Pitching]  → READY
-- source: description rewritten to remove the brand-led attribution; markers and next steps written for the existing cues
UPDATE public.drill_resources SET
  description = 'Where the front foot lands, and which way it points. The pitcher throws a normal delivery but with attention only on the landing: heel first, with the toes slightly closed — pointed a little toward third base for a right-hander. A front foot that lands turned open toward home lets the hips rotate early, and everything stored in the back leg leaks out before the arm gets to use it. Check the foot after every throw.',
  regression_notes = 'Walk through the stride and landing with no ball, checking the foot each time. The position has to be findable slowly before it can survive a delivery.',
  progression_notes = 'Throw at full effort and check whether the landing holds, then combine it with the stride direction line so both direction and foot angle are being checked at once.',
  success_markers = ARRAY['Front foot lands heel first rather than flat or on the toe', 'Toes point slightly closed rather than open toward the plate', 'Hips stay loaded until the foot is down']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = 'b22aa9c8-7cd1-4dc0-bba3-c66b03396e21';

-- Glove-Side Pull Drill — Front Side Control  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out the glove extension and the pull into the ribs
UPDATE public.drill_resources SET
  regression_notes = 'Do it dry with no ball, or have them hold a second ball in the glove hand and squeeze it into the ribs. Feeling where the glove ends up is the whole point.',
  progression_notes = 'Add full-effort throws and check whether the front side holds, then pair it with the hip lead work — a stable front side is what the hip is driving into.',
  success_markers = ARRAY['Glove extends toward the target during the stride rather than flopping', 'Glove elbow pulls tight into the ribs as the shoulder rotates', 'Chest finishes facing the target instead of the pitcher falling off to the side']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = 'b1c3653c-82a0-446e-a9cb-0dd5ebf09864';

