-- source: markers and next steps written for the existing description, which already sets out the chalk line and the landing spot beside it
UPDATE public.drill_resources SET
  regression_notes = 'Walk the stride with no ball and look at the foot each time. The line is feedback and it works just as well at walking pace.',
  progression_notes = 'Throw at full effort, then remove the line and see whether the direction holds. Pair with the heel-toe drill so the angle of the foot is checked as well as its position.',
  success_markers = ARRAY['Front foot lands consistently just to the glove side of the line', 'Stride neither crosses over the line nor lands well outside it', 'Pitcher checks their own landing spot without being asked']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = 'f47eba7c-bf41-4e1a-8a65-882f6fdcb0b1';

-- Kneel-Down (Wrist Snap) Drill — Release Point & Backspin  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out the kneeling pair at 15-20 feet and the backspin target
UPDATE public.drill_resources SET
  regression_notes = 'Move closer and use a lighter ball, or have a coach support the elbow so the arm cannot join in. Isolation is the mechanism and anything that preserves it is fine.',
  progression_notes = 'Stand up and add the torso, then the full delivery. The spin is what has to survive; if it disappears when the legs come in, go back.',
  success_markers = ARRAY['Ball spins straight back like a wheel rather than sideways', 'Only the forearm and wrist move — the shoulder stays quiet', 'Can repeat the backspin across most of a set rather than occasionally']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = '94124e82-c8f2-411b-9daa-f0a1a176663e';

-- The Rocker Drill — Hip Lead & Weight Shift  [Pitching]  → READY
-- source: description rewritten to remove the brand-led attribution; markers and next steps written for the existing cues
UPDATE public.drill_resources SET
  description = 'The hip lead, taught with a rocking start that makes it easy to feel. The pitcher rocks their weight back onto the back foot, then drives the front hip toward home plate while the shoulders stay back and tilted slightly uphill. The arm follows rather than leads. It is the single most useful mechanical correction for a youth pitcher losing both velocity and command, because a shoulder that arrives before the hip has spent the energy before the arm can use it.',
  regression_notes = 'Rock and hold without throwing, so the separated position can be felt and checked. A coach standing side-on can show them where the hip is relative to the shoulder.',
  progression_notes = 'Remove the rock so the hip lead happens from a normal leg lift, then throw at full effort to a catcher. Pair it with the Square Hips drill for the separation it creates.',
  success_markers = ARRAY['Front hip moves toward the plate before the front shoulder does', 'Shoulders stay tilted uphill through the stride rather than flattening', 'Weight stays back on the rock rather than drifting forward with it']::text[],
  practice_roles = ARRAY['isolate', 'teach']::text[],
  updated_at = now()
WHERE id = '03eab7d0-7e67-4143-91e5-b8e4e783014a';

-- Square Hips / Hip Lock Drill — Hip-Shoulder Separation  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out squaring the hips at landing while the shoulder stays back
UPDATE public.drill_resources SET
  regression_notes = 'Hold the position without throwing, or work it from a standing start with no leg lift. The separation is a feel and it needs to be found slowly first.',
  progression_notes = 'Add full-effort throws and check whether the separation survives, then build it into the complete delivery. The Rocker Drill is the natural partner since it builds the hip lead this depends on.',
  success_markers = ARRAY['Hips are square to the plate at front-foot landing', 'Throwing shoulder is still back at that moment rather than opening with the hips', 'Pitcher can feel and describe the twist across the middle']::text[],
  practice_roles = ARRAY['isolate', 'progress']::text[],
  updated_at = now()
WHERE id = 'ffc26e2a-7801-42b7-b610-9a996527e638';

-- Towel Drill — Arm Speed & Release Point  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out the towel, the target at release distance and the snap
UPDATE public.drill_resources SET
  regression_notes = 'Move the target closer and go at half speed. A pitcher who cannot reach the target will lunge to get there, which trains the opposite of what is wanted.',
  progression_notes = 'Move the target further out gradually, then throw a real ball and see whether the extension holds. This is a drill that can be done daily without arm cost, which is most of its value.',
  success_markers = ARRAY['Towel snaps the target consistently rather than falling short or overshooting', 'Full delivery is used, not a shortened arm action', 'Release point stays in the same place across a whole set']::text[],
  updated_at = now()
WHERE id = '93cf7e08-9bd0-48c3-a344-26e092c651e7';

-- Balance Point Drill — Leg Lift & Pause  [Pitching]  → READY
-- source: description rewritten to remove the brand-led closing attribution; markers and next steps written for the existing cues
UPDATE public.drill_resources SET
  description = 'The top of the delivery, held still. The pitcher lifts the front knee to about belt height and stops there for two to three seconds, front foot hanging straight down rather than tucked behind the knee, eyes on the target throughout. Then they finish the pitch. The pause turns a position that normally flashes past into something a pitcher can feel and a coach can correct, and a pitcher who cannot balance there is not going to repeat a delivery.',
  regression_notes = 'Hold without a ball, or with a fingertip on a fence. Balance is trainable in isolation, and the Flamingo drill is the version with the pitch removed entirely.',
  progression_notes = 'Shorten the pause until it disappears into a normal delivery, and check whether the balance holds at full effort. Add the hip lead work once the top of the delivery is stable.',
  success_markers = ARRAY['Holds the balance point for two seconds without wobbling', 'Front foot hangs straight down rather than tucking behind the back knee', 'Eyes stay on the target throughout the hold']::text[],
  updated_at = now()
WHERE id = 'a54d536f-e4f0-4dd5-91d2-d007bd274250';

-- The Swing Shuffle Drill — Momentum & Rhythm  [Pitching]  → READY
-- source: markers and next steps written for the existing description, which already sets out the lateral shuffle before delivery and the crow-hop comparison
UPDATE public.drill_resources SET
  regression_notes = 'Take one small step instead of a shuffle, or walk into the delivery. The lesson is that momentum adds power, and it works at any size of movement.',
  progression_notes = 'Shrink the shuffle toward a normal delivery and see how much of the momentum carries. Tell them plainly this is a feel drill rather than a game motion.',
  success_markers = ARRAY['Momentum flows into the delivery rather than the shuffle and the pitch being separate', 'Throws noticeably harder than from a dead stop', 'Lands under control despite the moving start']::text[],
  practice_roles = ARRAY['isolate', 'progress']::text[],
  updated_at = now()
WHERE id = 'cf56cda8-d397-4ed7-873b-560b78d6473e';

